#![allow(clippy::expect_used, clippy::unwrap_used, clippy::panic)]
// SPDX-License-Identifier: Apache-2.0
//! T4's bounded item page against `vectors/item-page.json`, generated by
//! `vectors/make-item-page-vectors.ts` from `apps/daemon/src/bounded-item-page.ts` and
//! `item-clip.ts`. Each case fixes the store page's answer, the newest item, and what is older;
//! the Rust page must make the same reads and return the same bytes, and clipping the same item.
//!
//! Ports the page rules those tests name:
//! - "an item larger than the page arrives reduced or summarized, never as a failed page"
//! - "paging a large item reads from storage only what each page holds"
//! - "an item's raw payloads are the part that makes tool calls huge" (the omission's `dropped`)

use std::cell::RefCell;
use std::collections::VecDeque;

use ace_json::Value;
use ace_store::reads::items::{ItemPageSource, PageError, PageRows, bounded_item_page, clip_item};

fn vectors() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/vectors/item-page.json");
    let text = std::fs::read_to_string(path).expect("read item-page.json");
    ace_json::parse(&text).expect("parse item-page.json")
}

fn array<'a>(value: &'a Value, key: &str) -> &'a [Value] {
    match value.get(key) {
        Some(Value::Array(items)) => items,
        _ => panic!("{key} is not an array"),
    }
}

fn text(value: &Value, key: &str) -> String {
    match value.get(key) {
        Some(Value::String(seen)) => seen.as_str().to_owned(),
        _ => panic!("{key} is not a string"),
    }
}

fn number(value: &Value, key: &str) -> f64 {
    match value.get(key) {
        Some(Value::Number(seen)) => seen.value(),
        _ => panic!("{key} is not a number"),
    }
}

fn parse(text: &str) -> Value {
    ace_json::parse(text).expect("parse fixture JSON")
}

fn optional_number(value: &Value, key: &str) -> Option<u64> {
    match value.get(key) {
        Some(Value::Number(seen)) => Some(seen.value() as u64),
        _ => None,
    }
}

#[derive(Debug, PartialEq)]
struct Call {
    call: String,
    before: u64,
    limit: Option<usize>,
    budget: Option<usize>,
}

/// The fixture's scripted source: answers the pages in order and records every read.
struct Scripted {
    pages: RefCell<VecDeque<Result<PageRows, PageError>>>,
    newest: Vec<Value>,
    has_before: Vec<(u64, bool)>,
    calls: RefCell<Vec<Call>>,
}

impl Scripted {
    fn new(case: &Value) -> Scripted {
        let pages = array(case, "pages")
            .iter()
            .map(|page| {
                if text(page, "kind") == "capacity" {
                    return Err(PageError::Capacity);
                }
                let item_seqs = parse(&text(page, "itemSeqs"));
                Ok(PageRows {
                    items: array(page, "items")
                        .iter()
                        .map(|item| match item {
                            Value::String(seen) => parse(seen.as_str()),
                            _ => panic!("page item is not a string"),
                        })
                        .collect(),
                    item_seqs: match item_seqs {
                        Value::Object(map) => map,
                        _ => panic!("itemSeqs"),
                    },
                    items_before: optional_number(page, "itemsBefore"),
                })
            })
            .collect();
        let has_before = match case.get("hasBefore") {
            Some(Value::Object(map)) => map
                .iter()
                .map(|(before, value)| {
                    (
                        before.as_str().parse::<u64>().expect("hasBefore key"),
                        matches!(value, Value::Bool(true)),
                    )
                })
                .collect(),
            _ => Vec::new(),
        };
        Scripted {
            pages: RefCell::new(pages),
            newest: array(case, "newest").to_vec(),
            has_before,
            calls: RefCell::new(Vec::new()),
        }
    }

    fn record(&self, call: Call) {
        self.calls.borrow_mut().push(call);
    }
}

impl ItemPageSource for Scripted {
    fn page(&self, before: u64, limit: usize, byte_limit: usize) -> Result<PageRows, PageError> {
        self.record(Call {
            call: "page".to_owned(),
            before,
            limit: Some(limit),
            budget: Some(byte_limit),
        });
        self.pages
            .borrow_mut()
            .pop_front()
            .expect("a scripted page")
    }

    fn newest_before(&self, before: u64) -> Option<(Value, u64)> {
        self.record(Call {
            call: "newestBefore".to_owned(),
            before,
            limit: None,
            budget: None,
        });
        self.newest.iter().find_map(|entry| {
            (optional_number(entry, "before") == Some(before))
                .then(|| (parse(&text(entry, "item")), number(entry, "seq") as u64))
        })
    }

    fn has_item_before(&self, before: u64) -> bool {
        self.record(Call {
            call: "hasItemBefore".to_owned(),
            before,
            limit: None,
            budget: None,
        });
        self.has_before
            .iter()
            .find(|(at, _)| *at == before)
            .is_some_and(|(_, has)| *has)
    }
}

/// Every bounded page is the TypeScript's bytes and makes the same reads, in order.
#[test]
fn every_bounded_page_is_the_typescripts() {
    let vectors = vectors();
    for case in array(&vectors, "pages") {
        let name = text(case, "name");
        let source = Scripted::new(case);
        let result = bounded_item_page(
            &source,
            "t",
            number(case, "before") as u64,
            number(case, "limit") as usize,
            number(case, "byteLimit") as usize,
        )
        .expect("a page");
        assert_eq!(
            ace_json::to_string(&result),
            text(case, "expected"),
            "{name}"
        );
        let expected: Vec<Call> = array(case, "calls")
            .iter()
            .map(|call| Call {
                call: text(call, "call"),
                before: number(call, "before") as u64,
                limit: optional_number(call, "limit").map(|limit| limit as usize),
                budget: optional_number(call, "budget").map(|budget| budget as usize),
            })
            .collect();
        assert_eq!(*source.calls.borrow(), expected, "{name} / reads");
    }
}

/// Clipping is the TypeScript's bytes, its UTF-16 cut and its count message included.
#[test]
fn every_clipped_item_is_the_typescripts() {
    let vectors = vectors();
    for case in array(&vectors, "clips") {
        let item = parse(&text(case, "item"));
        let clipped = clip_item(&item, number(case, "maxBytes") as isize);
        let expected = match case.get("expected") {
            Some(Value::String(seen)) => Some(seen.as_str().to_owned()),
            _ => None,
        };
        assert_eq!(
            clipped.as_ref().map(ace_json::to_string),
            expected,
            "{}",
            text(case, "name")
        );
    }
}
